/* ============================================
   Orchard — Premium Tech E-Commerce Store
   Design System & Shared Styles
   ============================================ */

/* CSS Variables */
:root {
  --color-primary: #1d1d1f;
  --color-secondary: #6e6e73;
  --color-bg: #ffffff;
  --color-bg-light: #f5f5f7;
  --color-bg-warm: #faf9f6;
  --color-accent: #0066cc;
  --color-accent-hover: #0077ed;
  --color-border: #d2d2d7;
  --color-border-light: #e8e8ed;
  --color-badge: #ff3b30;
  --color-success: #34c759;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 24px;
  --radius-xl: 28px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --transition-fast: 0.2s ease;
  --transition-base: 0.3s ease;
  --transition-slow: 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1024px;
  --section-gap: 80px;
  --section-gap-mobile: 56px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-stack);
  color: var(--color-primary);
  background: var(--color-bg);
  line-height: 1.47059;
  font-weight: 400;
  letter-spacing: -0.022em;
  overflow-x: hidden;
}

a {
  color: var(--color-accent);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--color-accent-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ============================================
   Typography
   ============================================ */

.heading-xl {
  font-size: 48px;
  font-weight: 600;
  line-height: 1.08349;
  letter-spacing: -0.003em;
}

.heading-lg {
  font-size: 40px;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.003em;
}

.heading-md {
  font-size: 32px;
  font-weight: 600;
  line-height: 1.125;
  letter-spacing: -0.003em;
}

.heading-sm {
  font-size: 24px;
  font-weight: 600;
  line-height: 1.16667;
  letter-spacing: -0.003em;
}

.heading-xs {
  font-size: 19px;
  font-weight: 600;
  line-height: 1.21053;
  letter-spacing: -0.003em;
}

.body-lg {
  font-size: 21px;
  font-weight: 400;
  line-height: 1.381;
  letter-spacing: -0.003em;
  color: var(--color-secondary);
}

.body-md {
  font-size: 17px;
  font-weight: 400;
  line-height: 1.47059;
  letter-spacing: -0.022em;
  color: var(--color-secondary);
}

.body-sm {
  font-size: 14px;
  font-weight: 400;
  line-height: 1.42859;
  letter-spacing: -0.016em;
  color: var(--color-secondary);
}

.caption {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.33337;
  letter-spacing: -0.01em;
  color: var(--color-secondary);
}

/* ============================================
   Layout Utilities
   ============================================ */

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: var(--section-gap) 0;
}

.section-bg {
  background: var(--color-bg-light);
}

.text-center {
  text-align: center;
}

.flex {
  display: flex;
}

.flex-col {
  flex-direction: column;
}

.items-center {
  align-items: center;
}

.justify-center {
  justify-content: center;
}

.gap-2 { gap: 8px; }
.gap-3 { gap: 12px; }
.gap-4 { gap: 16px; }
.gap-6 { gap: 24px; }
.gap-8 { gap: 32px; }

.mt-2 { margin-top: 8px; }
.mt-3 { margin-top: 12px; }
.mt-4 { margin-top: 16px; }
.mt-6 { margin-top: 24px; }
.mt-8 { margin-top: 32px; }

.mb-2 { margin-bottom: 8px; }
.mb-3 { margin-bottom: 12px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }
.mb-8 { margin-bottom: 32px; }

/* ============================================
   Navigation
   ============================================ */

.global-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 9999;
  background: rgba(255,255,255,0.72);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  height: 48px;
  display: flex;
  align-items: center;
}

.global-nav-inner {
  max-width: var(--max-width);
  width: 100%;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  font-size: 20px;
  font-weight: 600;
  color: var(--color-primary);
  text-decoration: none;
  letter-spacing: -0.5px;
}

.nav-logo:hover {
  text-decoration: none;
  color: var(--color-primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
}

.nav-links a {
  font-size: 12px;
  font-weight: 400;
  color: var(--color-primary);
  opacity: 0.8;
  text-decoration: none;
  letter-spacing: -0.01em;
  transition: opacity var(--transition-fast);
}

.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
  color: var(--color-primary);
}

.nav-icons {
  display: flex;
  align-items: center;
  gap: 20px;
}

.nav-icon-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  transition: background var(--transition-fast);
}

.nav-icon-btn:hover {
  background: rgba(0,0,0,0.06);
}

.nav-icon-btn svg {
  width: 18px;
  height: 18px;
  stroke: var(--color-primary);
  fill: none;
  stroke-width: 1.8;
}

/* Mobile nav toggle */
.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 4px;
  padding: 4px;
}

.nav-mobile-toggle span {
  display: block;
  width: 18px;
  height: 1.5px;
  background: var(--color-primary);
  border-radius: 1px;
  transition: transform 0.3s ease, opacity 0.3s ease;
}

/* ============================================
   Ribbon Banner
   ============================================ */

.ribbon-banner {
  background: var(--color-bg-light);
  text-align: center;
  padding: 12px 24px;
  font-size: 13px;
  color: var(--color-primary);
  margin-top: 48px;
}

.ribbon-banner a {
  color: var(--color-accent);
}

/* ============================================
   Buttons
   ============================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  border-radius: 980px;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.33337;
  letter-spacing: -0.01em;
  transition: all var(--transition-fast);
  text-decoration: none;
  cursor: pointer;
}

.btn-primary {
  background: var(--color-accent);
  color: #fff;
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  text-decoration: none;
  color: #fff;
}

.btn-secondary {
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
}

.btn-secondary:hover {
  background: var(--color-accent);
  color: #fff;
  text-decoration: none;
}

.btn-group {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}

/* ============================================
   Product Cards & Carousels
   ============================================ */

.carousel-section {
  padding: var(--section-gap) 0;
}

.carousel-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
  padding: 0 24px;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}

.carousel-title-wrap {
  text-align: left;
}

.carousel-nav {
  display: flex;
  gap: 12px;
}

.carousel-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(0,0,0,0.04);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition-fast), opacity var(--transition-fast);
  cursor: pointer;
}

.carousel-btn:hover {
  background: rgba(0,0,0,0.08);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-btn svg {
  width: 16px;
  height: 16px;
  stroke: var(--color-primary);
  fill: none;
  stroke-width: 2;
}

.carousel-scroll {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: 4px 24px 24px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.carousel-scroll::-webkit-scrollbar {
  display: none;
}

/* Hide scrollbar but keep functionality */
.carousel-scroll {
  -ms-overflow-style: none;
}

/* Product Card */
.product-card {
  flex: 0 0 320px;
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  scroll-snap-align: start;
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.product-card-image {
  width: 100%;
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg-light);
  position: relative;
  overflow: hidden;
}

.product-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.product-card-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--color-badge);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 12px;
  letter-spacing: 0.02em;
}

.product-card-content {
  padding: 20px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-card-name {
  font-size: 17px;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 4px;
}

.product-card-tagline {
  font-size: 14px;
  color: var(--color-secondary);
  margin-bottom: 12px;
  line-height: 1.4;
}

.product-card-price {
  font-size: 15px;
  font-weight: 500;
  color: var(--color-primary);
  margin-bottom: 2px;
}

.product-card-monthly {
  font-size: 13px;
  color: var(--color-secondary);
  margin-bottom: 16px;
}

.product-card-actions {
  margin-top: auto;
  display: flex;
  gap: 12px;
}

/* Small card variant */
.product-card-sm {
  flex: 0 0 260px;
}

.product-card-sm .product-card-image {
  height: 180px;
}

/* Wide card variant */
.product-card-wide {
  flex: 0 0 400px;
}

/* ============================================
   Hero Product Grid (Homepage)
   ============================================ */

.hero-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  max-width: calc(var(--max-width) + 48px);
  margin: 0 auto;
  padding: 0 24px;
}

.hero-tile {
  position: relative;
  background: var(--color-bg-light);
  border-radius: var(--radius-xl);
  overflow: hidden;
  min-height: 520px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 48px 32px 32px;
  transition: transform var(--transition-base);
}

.hero-tile:hover {
  transform: scale(1.005);
}

.hero-tile-dark {
  background: var(--color-primary);
  color: #fff;
}

.hero-tile-dark .hero-tile-title,
.hero-tile-dark .hero-tile-tagline {
  color: #fff;
}

.hero-tile-title {
  font-size: 40px;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.003em;
  margin-bottom: 8px;
}

.hero-tile-tagline {
  font-size: 19px;
  font-weight: 400;
  color: var(--color-secondary);
  margin-bottom: 16px;
}

.hero-tile-image {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 24px 0;
}

.hero-tile-image img {
  max-height: 280px;
  width: auto;
  object-fit: contain;
}

.hero-tile-actions {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}

/* ============================================
   Entertainment Tabs
   ============================================ */

.entertainment-tabs {
  display: flex;
  justify-content: center;
  gap: 32px;
  margin-bottom: 32px;
  border-bottom: 1px solid var(--color-border-light);
  padding-bottom: 0;
}

.entertainment-tab {
  font-size: 17px;
  font-weight: 400;
  color: var(--color-secondary);
  padding: 12px 4px;
  position: relative;
  cursor: pointer;
  background: none;
  border: none;
  transition: color var(--transition-fast);
}

.entertainment-tab:hover {
  color: var(--color-primary);
}

.entertainment-tab.active {
  color: var(--color-primary);
  font-weight: 500;
}

.entertainment-tab.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-primary);
  border-radius: 1px;
}

.entertainment-panel {
  display: none;
}

.entertainment-panel.active {
  display: block;
}

/* Entertainment Card */
.ent-card {
  flex: 0 0 380px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  scroll-snap-align: start;
}

.ent-card-image {
  width: 100%;
  height: 220px;
  background: linear-gradient(135deg, #1d1d1f 0%, #434344 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.ent-card-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 24px;
  background: linear-gradient(transparent, rgba(0,0,0,0.7));
  color: #fff;
}

.ent-card-title {
  font-size: 19px;
  font-weight: 600;
  margin-bottom: 4px;
}

.ent-card-subtitle {
  font-size: 14px;
  opacity: 0.9;
  margin-bottom: 12px;
}

.ent-card-cta {
  font-size: 14px;
  color: #fff;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.ent-card-cta:hover {
  text-decoration: underline;
  color: #fff;
}

/* ============================================
   Icon Bar (Product Categories)
   ============================================ */

.icon-bar {
  display: flex;
  justify-content: center;
  gap: 40px;
  flex-wrap: wrap;
  padding: 32px 24px;
}

.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-primary);
  transition: transform var(--transition-fast);
}

.icon-bar-item:hover {
  transform: scale(1.05);
  text-decoration: none;
  color: var(--color-primary);
}

.icon-bar-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-sm);
  background: var(--color-bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.icon-bar-label {
  font-size: 12px;
  font-weight: 400;
  color: var(--color-primary);
}

/* ============================================
   Help & Support Cards
   ============================================ */

.help-card {
  flex: 0 0 300px;
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-sm);
  scroll-snap-align: start;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.help-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.help-card-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 20px;
}

.help-card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.help-card-desc {
  font-size: 14px;
  color: var(--color-secondary);
  line-height: 1.4;
}

/* ============================================
   Store Difference Cards
   ============================================ */

.difference-card {
  flex: 0 0 280px;
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  scroll-snap-align: start;
  text-align: center;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.difference-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.difference-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  font-size: 24px;
}

.difference-card-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 6px;
}

.difference-card-desc {
  font-size: 13px;
  color: var(--color-secondary);
  line-height: 1.4;
}

/* ============================================
   Savings Cards
   ============================================ */

.savings-card {
  flex: 0 0 300px;
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  scroll-snap-align: start;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.savings-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.savings-card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.savings-card-desc {
  font-size: 14px;
  color: var(--color-secondary);
  line-height: 1.4;
}

/* ============================================
   Quick Links
   ============================================ */

.quick-links {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 0 24px;
}

.quick-link-btn {
  padding: 10px 20px;
  border-radius: 980px;
  background: var(--color-bg-light);
  color: var(--color-primary);
  font-size: 14px;
  font-weight: 400;
  transition: background var(--transition-fast);
}

.quick-link-btn:hover {
  background: var(--color-border-light);
}

/* ============================================
   Category Hero
   ============================================ */

.category-hero {
  background: var(--color-bg-light);
  padding: 120px 24px 80px;
  text-align: center;
}

.category-hero-title {
  font-size: 56px;
  font-weight: 600;
  line-height: 1.07143;
  letter-spacing: -0.005em;
  margin-bottom: 12px;
}

.category-hero-subtitle {
  font-size: 21px;
  color: var(--color-secondary);
  margin-bottom: 24px;
}

/* Sticky Section Nav */
.section-nav {
  position: sticky;
  top: 48px;
  z-index: 100;
  background: rgba(255,255,255,0.88);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border-light);
  padding: 12px 24px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.section-nav::-webkit-scrollbar {
  display: none;
}

.section-nav-inner {
  display: flex;
  justify-content: center;
  gap: 32px;
  max-width: var(--max-width);
  margin: 0 auto;
  min-width: max-content;
}

.section-nav a {
  font-size: 14px;
  font-weight: 400;
  color: var(--color-secondary);
  white-space: nowrap;
  transition: color var(--transition-fast);
}

.section-nav a:hover {
  color: var(--color-primary);
  text-decoration: none;
}

.section-nav a.active {
  color: var(--color-primary);
  font-weight: 500;
}

/* ============================================
   Shopping Guide Cards
   ============================================ */

.guide-card {
  flex: 0 0 320px;
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  scroll-snap-align: start;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.guide-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.guide-card-image {
  width: 100%;
  height: 180px;
  background: var(--color-bg-light);
  display: flex;
  align-items: center;
  justify-content: center;
}

.guide-card-content {
  padding: 24px;
}

.guide-card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.guide-card-desc {
  font-size: 14px;
  color: var(--color-secondary);
  line-height: 1.4;
}

/* ============================================
   Brand Collaboration
   ============================================ */

.brand-collab {
  background: linear-gradient(135deg, #1d1d1f 0%, #2d2d2f 100%);
  color: #fff;
  padding: var(--section-gap) 24px;
